    for (int i = 1; i < n; ++i) {
        if (a[i] % 2 == 1)
            odd[i] = odd[i - 1] + 1;
        else
            odd[i] = odd[i - 1] - 1;
    }

    std::vector<int> price(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        price[i] = std::abs(a[i + 1] - a[i]);
